}
.mm-ocd #mobile-menu.mm-spn {
  --mm-spn-item-height: 56px !important;
  --mm-spn-item-indent: 18px !important;
  --mm-spn-line-height: 20px !important;
  background: #f8f8f8 !important;
  color: #111827 !important;
  font-size: 15px !important;
  font-weight: 700 !important;
}
/* عنوان القائمة الحقيقي: after */
.mm-ocd #mobile-menu.mm-spn.mm-spn--navbar:after {
  content: attr(data-mm-spn-title) !important;
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 70px !important;
  right: 70px !important;
  width: auto !important;
  height: 56px !important;
  min-width: 0 !important;
  min-height: 56px !important;
  max-width: none !important;
  max-height: 56px !important;
  line-height: 56px !important;
  padding: 0 !important;
  margin: 0 !important;
  z-index: 22 !important;
  color: rgba(17, 24, 39, 0.68) !important;
  -webkit-text-fill-color: rgba(17, 24, 39, 0.68) !important;
  font-size: 14px !important;
  font-weight: 800 !important;
  text-align: center !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  background: transparent !important;
  box-shadow: none !important;
  border: 0 !important;
  border-radius: 0 !important;
  transform: none !important;
  pointer-events: none !important;
}
/* شريط الهيدر خلف العنوان */
