.mm-ocd #mobile-menu.mm-spn.mm-spn--navbar ul.mm-spn--open:after,
.mm-ocd #mobile-menu.mm-spn.mm-spn--navbar ul.mm-spn--parent:before,
.mm-ocd #mobile-menu.mm-spn.mm-spn--navbar ul.mm-spn--parent:after {
  content: none !important;
  display: none !important;
  width: 0 !important;
  height: 0 !important;
  border: 0 !important;
  opacity: 0 !important;
  transform: none !important;
  background: transparent !important;
  pointer-events: none !important;
